  lines.append(row)
 p=subprocess.run(['tmp/engine_test'],input=('\n'.join(lines)+'\n').encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if p.returncode:raise RuntimeError(p.stderr.decode())
 o=p.stdout.decode().splitlines();at=len(sts)
 for v,r,aa in bursts:A=int(o[at]);at+=1+A
 return tuple(map(int,o[at].split()))
random.seed(2025)
for trial in range(200):
 V=random.randint(2,4);C=random.randint(0,8)
 cost=[random.randint(1,8),0,[random.randint(0,5) for _ in range(3)]];cost[1]=random.randint(cost[0],20)
 sts=[];hps=[];allb=[]
 totalR=0
 for v in range(V):
  R=random.randint(1,3);totalR+=R
  st=[0]
