    r=random.randrange(R);end=st[r+1] if r+1<R else st[r]+50
    aa.append(random.randrange(st[r],min(end,st[r]+50)))
   allb.append((v,rep,aa))
 per=[]
 for v,(st,hp) in enumerate(zip(sts,hps)):
